// Prepares android/app/build.gradle for releases: version from package.json and release signing from keystore.properties.
// Safe to run repeatedly. Run after `cap sync` (the release script does it for you).
import fs from "node:fs"

const gradle = "android/app/build.gradle"
if (!fs.existsSync(gradle)) {
  console.error("✗ android/ not found. Create it with:  pnpm build && pnpm exec cap add android")
  process.exit(1)
}
let g = fs.readFileSync(gradle, "utf8")
// Built from parts on purpose: the brand rename tool would otherwise rewrite this check.
const OLD_APP_ID = ["com", "convertlab", "app"].join(".")
if (g.includes(OLD_APP_ID)) {
  console.error(`✗ android/ still uses the old app id (${OLD_APP_ID}). Recreate it:  rm -rf android && pnpm build && pnpm exec cap add android`)
  process.exit(1)
}

const pkg = JSON.parse(fs.readFileSync("package.json", "utf8"))
const [major, minor, patch] = String(pkg.version || "1.0.0").split(".").map((n) => parseInt(n, 10) || 0)
const versionName = process.env.VERSION_NAME || pkg.version || "1.0.0"
// 3.0.0 -> 30000, 3.1.4 -> 30104: grows with every semver bump, which is what Google Play requires.
const versionCode = parseInt(process.env.VERSION_CODE || String(major * 10000 + minor * 100 + patch), 10)

g = g.replace(/versionCode \d+/, `versionCode ${versionCode}`).replace(/versionName "[^"]*"/, `versionName "${versionName}"`)

if (!g.includes("clinexia-signing")) {
  const header = `// clinexia-signing: release signing comes from ../keystore.properties (never commit that file)
def keystorePropertiesFile = rootProject.file("../keystore.properties")
def keystoreProperties = new Properties()
if (keystorePropertiesFile.exists()) {
    keystorePropertiesFile.withInputStream { keystoreProperties.load(it) }
}

`
  const signing = `    signingConfigs {
        release {
            if (keystoreProperties['storeFile']) {
                def ks = new File(keystoreProperties['storeFile'])
                storeFile ks.isAbsolute() ? ks : rootProject.file("../" + keystoreProperties['storeFile'])
                storePassword keystoreProperties['storePassword']
                keyAlias keystoreProperties['keyAlias']
                keyPassword keystoreProperties['keyPassword']
            }
        }
    }
`
  if (!g.includes("\nandroid {") || !g.includes("    buildTypes {\n        release {\n            minifyEnabled false")) {
    console.error("✗ android/app/build.gradle has an unexpected layout; add the signing configuration by hand (see docs/RELEASE.md).")
    process.exit(1)
  }
  g = g.replace("\nandroid {", "\n" + header + "android {")
  g = g.replace("    buildTypes {\n        release {\n            minifyEnabled false", signing + "    buildTypes {\n        release {\n            if (keystoreProperties['storeFile']) {\n                signingConfig signingConfigs.release\n            }\n            minifyEnabled false")
}

fs.writeFileSync(gradle, g)
console.log(`  android/app/build.gradle: versionName ${versionName}, versionCode ${versionCode}, signing ${fs.existsSync("keystore.properties") ? "enabled (keystore.properties found)" : "NOT configured (no keystore.properties)"}`)
__CL_EOF__
put "scripts/create-keystore.sh" <<'__CL_EOF__'
#!/usr/bin/env bash
# Creates your release signing key and keystore.properties.   Usage: pnpm keystore:create
# KEEP THE .jks FILE AND ITS PASSWORDS SAFE AND BACKED UP OUTSIDE THIS REPOSITORY. Both are git-ignored.
# If you use Play App Signing (recommended), this is only your UPLOAD key: Google can reset it if it is lost.
# Without Play App Signing, losing it means you can never update the app.
set -euo pipefail
cd "$(dirname "$0")/.."

find_keytool() {
  if command -v keytool >/dev/null 2>&1; then command -v keytool; return; fi
  for d in "${JAVA_HOME:-}" "$HOME/android-studio/jbr" "/opt/android-studio/jbr" "/usr/local/android-studio/jbr" "/snap/android-studio/current/android-studio/jbr" "/Applications/Android Studio.app/Contents/jbr/Contents/Home"; do
    [ -n "$d" ] && [ -x "$d/bin/keytool" ] && { echo "$d/bin/keytool"; return; }
  done
  return 1
}
KEYTOOL="$(find_keytool)" || { echo "✗ keytool not found. Install Android Studio (it bundles a JDK) or set JAVA_HOME."; exit 1; }

STORE_FILE="${KEYSTORE_FILE:-clinexia-release.jks}"
ALIAS="${KEY_ALIAS:-clinexia}"
if [ -f "$STORE_FILE" ] || [ -f keystore.properties ]; then
  echo "✗ $STORE_FILE or keystore.properties already exists. Refusing to overwrite a signing key. Move them away first if you really want a new one."
  exit 1
fi

read -r -s -p "Choose a keystore password (min 6 characters): " STOREPASS; echo
read -r -s -p "Repeat it: " STOREPASS2; echo
[ "$STOREPASS" = "$STOREPASS2" ] || { echo "✗ Passwords do not match."; exit 1; }
[ "${#STOREPASS}" -ge 6 ] || { echo "✗ Use at least 6 characters."; exit 1; }
read -r -p "Your name or organisation (for the certificate) [Clinexia]: " CN; CN="${CN:-Clinexia}"
read -r -p "Two-letter country code [NG]: " CC; CC="${CC:-NG}"

export STOREPASS
"$KEYTOOL" -genkeypair -v -keystore "$STORE_FILE" -alias "$ALIAS" -keyalg RSA -keysize 2048 -validity 10000 \
  -storepass:env STOREPASS -keypass:env STOREPASS -dname "CN=$CN, C=$CC"

umask 077
cat > keystore.properties <<PROPS
storeFile=$STORE_FILE
storePassword=$STOREPASS
keyAlias=$ALIAS
keyPassword=$STOREPASS
PROPS
unset STOREPASS

echo
echo "✓ Created $STORE_FILE and keystore.properties (both git-ignored)."
echo "  NOW: copy $STORE_FILE and the password to a safe place outside this repository (password manager + an offline copy)."
echo "  Then build:  pnpm release:apk"
__CL_EOF__
put "scripts/release-android.sh" <<'__CL_EOF__'
#!/usr/bin/env bash
# Builds the Android release.
#   pnpm release:apk     signed APK  -> dist/Clinexia-<version>.apk  (+ .sha256)   direct download and Firebase App Distribution
#   pnpm release:aab     signed AAB  -> dist/Clinexia-<version>.aab                Google Play
#   pnpm release:all     both
# DEBUG_APK=1 pnpm release:apk builds an installable DEBUG apk without a keystore (testing only, never publish it).
set -euo pipefail
cd "$(dirname "$0")/.."

WHAT="${1:-apk}"
case "$WHAT" in apk|aab|all) ;; *) echo "usage: release-android.sh [apk|aab|all]"; exit 1;; esac

die() { echo "✗ $*" >&2; exit 1; }

[ -z "${CAPACITOR_SERVER_URL:-}" ] || die "CAPACITOR_SERVER_URL is set. A release must bundle the app, not load your dev server. Run: unset CAPACITOR_SERVER_URL"
command -v pnpm >/dev/null 2>&1 || die "pnpm is required."

# --- JDK (Android Studio bundles one) and Android SDK
if ! command -v java >/dev/null 2>&1 && [ -z "${JAVA_HOME:-}" ]; then
  for d in "$HOME/android-studio/jbr" "/opt/android-studio/jbr" "/usr/local/android-studio/jbr" "/snap/android-studio/current/android-studio/jbr" "/Applications/Android Studio.app/Contents/jbr/Contents/Home"; do
    [ -x "$d/bin/java" ] && { export JAVA_HOME="$d"; export PATH="$JAVA_HOME/bin:$PATH"; break; }
  done
fi
command -v java >/dev/null 2>&1 || die "Java not found. Install Android Studio (it bundles a JDK) or set JAVA_HOME."
SDK="${ANDROID_HOME:-${ANDROID_SDK_ROOT:-}}"
if [ -z "$SDK" ] && [ -f android/local.properties ]; then SDK="$(sed -n 's/^sdk.dir=//p' android/local.properties | head -1)"; fi
if [ -z "$SDK" ]; then for d in "$HOME/Android/Sdk" "$HOME/Library/Android/sdk"; do [ -d "$d" ] && SDK="$d" && break; done; fi
[ -n "$SDK" ] && [ -d "$SDK" ] || die "Android SDK not found. Install it through Android Studio, then: export ANDROID_HOME=\$HOME/Android/Sdk"
export ANDROID_HOME="$SDK"

DEBUG="${DEBUG_APK:-0}"
if [ "$DEBUG" != "1" ] && [ ! -f keystore.properties ]; then
  die "No keystore.properties. Create your signing key first:  pnpm keystore:create   (or DEBUG_APK=1 for a test-only debug apk)"
fi

VERSION="$(node -p "require('./package.json').version")"
mkdir -p dist

echo "▶ 1/4  Building the web bundle (static export)"
pnpm build
[ -f out/index.html ] || die "out/index.html missing: the web build failed."

echo "▶ 2/4  Syncing the Android project"
[ -d android ] || pnpm exec cap add android
pnpm exec cap sync android
if grep -q '"url"' android/app/src/main/assets/capacitor.config.json 2>/dev/null; then
  die "android/.../capacitor.config.json contains a server url (a dev server got baked in). Run: unset CAPACITOR_SERVER_URL && pnpm exec cap sync android"
fi
node scripts/android-setup.mjs

echo "▶ 3/4  Building with Gradle"
cd android
chmod +x gradlew
if [ "$DEBUG" = "1" ]; then
  ./gradlew --no-daemon assembleDebug
else
  case "$WHAT" in apk) ./gradlew --no-daemon assembleRelease ;; aab) ./gradlew --no-daemon bundleRelease ;; all) ./gradlew --no-daemon assembleRelease bundleRelease ;; esac
fi
cd ..

echo "▶ 4/4  Collecting files in dist/"
sha() { if command -v sha256sum >/dev/null 2>&1; then sha256sum "$1" | cut -d' ' -f1; else shasum -a 256 "$1" | cut -d' ' -f1; fi; }
verify() {
  local apksigner; apksigner="$(ls -1 "$ANDROID_HOME"/build-tools/*/apksigner 2>/dev/null | sort -V | tail -1 || true)"
  if [ -n "$apksigner" ]; then "$apksigner" verify --print-certs "$1" >/dev/null 2>&1 && echo "  ✓ signature verified: $(basename "$1")" || echo "  ⚠ apksigner could not verify $(basename "$1")"; fi
}
if [ "$DEBUG" = "1" ]; then
  cp android/app/build/outputs/apk/debug/app-debug.apk "dist/Clinexia-$VERSION-DEBUG.apk"
  echo "  dist/Clinexia-$VERSION-DEBUG.apk (debug build: for your own testing only)"
else
  if [ "$WHAT" = "apk" ] || [ "$WHAT" = "all" ]; then
    SRC="android/app/build/outputs/apk/release/app-release.apk"
    [ -f "$SRC" ] || die "Signed APK not found ($SRC). Is keystore.properties valid?"
    cp "$SRC" "dist/Clinexia-$VERSION.apk"
    echo "$(sha "dist/Clinexia-$VERSION.apk")  Clinexia-$VERSION.apk" > "dist/Clinexia-$VERSION.apk.sha256"
    verify "dist/Clinexia-$VERSION.apk"
  fi
  if [ "$WHAT" = "aab" ] || [ "$WHAT" = "all" ]; then
    SRC="android/app/build/outputs/bundle/release/app-release.aab"
    [ -f "$SRC" ] || die "Signed AAB not found ($SRC)."
    cp "$SRC" "dist/Clinexia-$VERSION.aab"
  fi
fi

echo
ls -lh dist | sed 's/^/  /'
if [ -f "dist/Clinexia-$VERSION.apk.sha256" ]; then
  echo
  echo "  For the landing page (Vercel → Environment Variables), after you upload the APK somewhere (a GitHub Release is ideal):"
  echo "    NEXT_PUBLIC_APK_URL=<direct link to Clinexia-$VERSION.apk>"
  echo "    NEXT_PUBLIC_APK_SHA256=$(cut -d' ' -f1 "dist/Clinexia-$VERSION.apk.sha256")"
  echo "    NEXT_PUBLIC_APK_VERSION=$VERSION"
fi
__CL_EOF__
put "scripts/firebase-distribute.sh" <<'__CL_EOF__'
#!/usr/bin/env bash
# Uploads the signed APK to Firebase App Distribution so testers get it by invitation link.   Usage: pnpm release:firebase [path-to-apk]
# One-time setup is in docs/RELEASE.md. Needs:
#   FIREBASE_APP_ID   e.g. 1:1234567890:android:abcdef123456   (Firebase console → Project settings → Your apps)
#   FIREBASE_GROUPS   tester group alias(es), comma separated, e.g. testers
# and a login:  npx firebase-tools login   (or GOOGLE_APPLICATION_CREDENTIALS pointing at a service-account JSON, for CI)
# No google-services.json is needed: App Distribution works without the Firebase SDK in the app.
set -euo pipefail
cd "$(dirname "$0")/.."

APK="${1:-$(ls -1t dist/Clinexia-*.apk 2>/dev/null | grep -v DEBUG | head -1 || true)}"
[ -n "$APK" ] && [ -f "$APK" ] || { echo "✗ No APK found. Build one first:  pnpm release:apk"; exit 1; }
case "$APK" in *DEBUG*) echo "✗ Refusing to distribute a DEBUG build."; exit 1;; esac
: "${FIREBASE_APP_ID:?Set FIREBASE_APP_ID (Firebase console → Project settings → Your apps → App ID)}"
: "${FIREBASE_GROUPS:?Set FIREBASE_GROUPS (the tester group alias, e.g. testers)}"

NOTES="${RELEASE_NOTES:-$(git log -5 --pretty='- %s' 2>/dev/null || echo 'New build')}"
echo "▶ Uploading $(basename "$APK") to Firebase App Distribution (groups: $FIREBASE_GROUPS)"
npx --yes firebase-tools appdistribution:distribute "$APK" \
  --app "$FIREBASE_APP_ID" \
  --groups "$FIREBASE_GROUPS" \
  --release-notes "$NOTES"
echo
echo "✓ Uploaded. Public invite link for the landing page:"
echo "  Firebase console → App Distribution → Testers & Groups → your group → Invite links → copy,"
echo "  then set NEXT_PUBLIC_FIREBASE_DIST_URL on the website and redeploy."
__CL_EOF__
put "docs/RELEASE.md" <<'__CL_EOF__'
# Releasing Clinexia on Android

Four ways to get the app to people. They all start from the same signed build.

| Channel | Best for | Command |
|---|---|---|
| **Direct APK** | Anyone, right now, from your website | `pnpm release:apk` |
| **Firebase App Distribution** | Testers and early users by invitation link | `pnpm release:apk` then `pnpm release:firebase` |
| **Google Play** | Everyone, with automatic updates | `pnpm release:aab`, then upload in Play Console |
| **Windows (Microsoft Store)** | Windows PCs | Packaged from the web app with PWABuilder (see the web repository README) |

## 0. Requirements (once)
- **Android Studio** (it installs the Android SDK and a JDK). Then: `export ANDROID_HOME=$HOME/Android/Sdk`
- **Node.js 22+** and **pnpm**
- The Android project created with the Clinexia app id: `pnpm build && pnpm exec cap add android`
- `.env.production` with `NEXT_PUBLIC_ANALYTICS_URL=https://<your app address>` (see `.env.example`)

## 1. Create your signing key (once, and back it up)
```bash
pnpm keystore:create
```
It creates `clinexia-release.jks` and `keystore.properties` (both git-ignored). **Copy the `.jks` file and its password somewhere safe outside this repository.** With **Play App Signing** (recommended, turned on in Play Console) this is only your *upload* key and Google can reset it if you lose it. For APKs you distribute yourself, the key is permanent: lose it and your users cannot update, they must uninstall and reinstall.

## 2. Build
```bash
pnpm release:apk     # dist/Clinexia-<version>.apk and .sha256
pnpm release:aab     # dist/Clinexia-<version>.aab   (for Google Play)
pnpm release:all     # both
```
- The version comes from `package.json` (`version`). **Raise it for every release.** `3.0.0` becomes `versionCode 30000`, `3.1.4` becomes `30104`, which always grows, as Google Play requires.
- The script refuses to build if `CAPACITOR_SERVER_URL` is set or if a dev-server URL was baked into the app.
- `DEBUG_APK=1 pnpm release:apk` makes a test-only debug APK that needs no keystore. Never publish it.
- Always install the APK on a real phone and check it before you share it.

## 3. Direct APK download (from your website)
1. Create a **GitHub Release** (or any file host) and upload `dist/Clinexia-<version>.apk`.
2. Copy the direct download link of the file.
3. On the website (Vercel → Environment Variables) set `NEXT_PUBLIC_APK_URL`, `NEXT_PUBLIC_APK_SHA256` (the build prints it) and `NEXT_PUBLIC_APK_VERSION`, then redeploy. The landing page shows the download, the checksum and install steps.

People installing an APK from outside Google Play must allow installs from their browser or file manager once, and Play Protect may show a warning. The landing page explains this.

## 4. Firebase App Distribution (testers)
One-time setup:
1. Create a project in the [Firebase console](https://console.firebase.google.com).
2. **Add app → Android**, package name **`com.clinexia.app`**. You can skip downloading `google-services.json`: App Distribution does not need it.
3. **Release & Monitor → App Distribution → Get started**. Create a tester group (alias, for example `testers`).
4. Copy the **App ID** (Project settings → Your apps), which looks like `1:1234567890:android:abcdef123456`.
5. Log in on your computer: `npx firebase-tools login`.

Each release:
```bash
export FIREBASE_APP_ID="1:1234567890:android:abcdef123456"
export FIREBASE_GROUPS="testers"
pnpm release:firebase
```
Testers get an email. For a public join link: App Distribution → Testers & Groups → your group → **Invite links**. Set it as `NEXT_PUBLIC_FIREBASE_DIST_URL` on the website.

## 5. Google Play
1. Create a [Play Console](https://play.google.com/console) developer account (one-time fee; new personal accounts must run a closed test with testers before going public. Check Google's current rules).
2. **Create app**: name *Clinexia: Clinical Toolkit*, free, app.
3. Turn on **Play App Signing** when you upload the first bundle.
4. Upload `dist/Clinexia-<version>.aab` to **Testing → Internal testing** first.
5. Fill the store listing from `store/play/listing.md` and upload the graphics in `store/play/`.
6. **App content**: privacy policy URL (`https://<your app address>/privacy`), Data safety (`store/play/data-safety.md`), content rating, target audience (18+), ads (none), health apps declaration.
7. Test, then promote the release to production.
8. When the listing is live, set `NEXT_PUBLIC_PLAY_STORE_URL` on the website and redeploy.

## 6. Checklist for every release
- [ ] `pnpm typecheck && pnpm test` pass
- [ ] Version raised in `package.json`
- [ ] `unset CAPACITOR_SERVER_URL`
- [ ] Built on a clean checkout, installed on a real phone, and tried: a calculator, a dose with mg and mL, the back button, dark mode
- [ ] Release notes written
- [ ] The keystore is backed up

## Troubleshooting
| Problem | Fix |
|---|---|
| `Java not found` | Install Android Studio, or set `JAVA_HOME` to its `jbr` folder |
| `Android SDK not found` | `export ANDROID_HOME=$HOME/Android/Sdk` |
| `No keystore.properties` | `pnpm keystore:create`, or `DEBUG_APK=1` for a test build |
| `android/ still uses the old app id` | `rm -rf android && pnpm build && pnpm exec cap add android` |
| Play says the version code was already used | Raise `version` in `package.json` |
| App opens but is blank | A dev-server URL was baked in: `unset CAPACITOR_SERVER_URL`, rebuild |
__CL_EOF__
put "store/play/listing.md" <<'__CL_EOF__'
# Google Play listing: Clinexia

Copy and paste into Play Console → Grow → Store presence → Main store listing. Limits are Google's.

## App name (30 characters max)
```
Clinexia: Clinical Toolkit
```

## Short description (80 characters max)
```
Clinical calculators, drug doses in mg and mL, unit conversions. Works offline.
```

## Full description (4000 characters max)
```
Clinexia is a complete clinical toolkit for your phone. Calculators, drug dosing, unit conversions and reference tools, in one fast app that works without an internet connection.

WHAT YOU GET
• 150+ calculators across renal, cardiovascular, hematology, clinical chemistry, microbiology, oncology, stem cell and transplant, general clinical and laboratory work
• Drug dosing helpers for weight-based and body-surface-based doses. Single-drug dose calculators show the dose in mg for one administration and, when you enter the product strength from the label (for example 125 mg in 5 mL), the volume in mL per dose. Nothing is assumed: no strength entered, no volume shown
• Estimators such as eGFR, creatinine clearance, body surface area and ideal body weight, clearly labelled as estimates
• Unit conversions for mass, volume, length, temperature, pressure, energy, time, mass concentration and molar concentration
• Laboratory tools: dilutions, solution preparation, spectrophotometry, microbiology counts and McFarland standards
• Reference ranges for hematology and clinical chemistry
• Every calculator shows its formula, notes, limitations and a versioned source, so you can check the original

DESIGNED FOR REAL USE
• Works offline: everything is built into the app
• No account and no sign-up
• Light, dark or system theme, and adjustable text size
• History and favorites stay on your device
• Fast search across calculators

FOR
Clinicians, nurses, pharmacists, laboratory staff, medical and nursing students, and anyone who needs reliable clinical arithmetic.

PRIVACY
No account. Your inputs, results, history and favorites stay on your device. The app can send an anonymous usage count (a random installation ID and which tool was used, never what you typed). You can turn it off in Settings.

IMPORTANT
Clinexia is a calculation and reference utility for educational and clinical reference use. It is not a medical device and does not replace clinical judgement, local protocols, product information or validated laboratory procedures. Always verify results before acting on them.
```

## Settings to choose
| Field | Value |
|---|---|
| App category | Medical |
| Tags | Medical, Health, Education (choose the closest offered) |
| Contact email | (your support email: required) |
| Website | your landing page address |
| Privacy policy URL | `https://<your app address>/privacy` |
| Target audience | 18 and over (it is a professional/reference tool; this also avoids the Families policy) |
| Ads | No |
| In-app purchases | No |
| Government app | No |
| Health apps declaration | A medical/clinical reference and calculation app. It does not diagnose, treat or monitor a person, and it shows a disclaimer |
| Content rating (IARC questionnaire) | No violence, sexual content, language, gambling, drugs promotion or user-generated content. Expect the lowest rating |

## Graphics (in this folder)
| File | Use | Size |
|---|---|---|
| `icon-512.png` | App icon | 512 × 512 |
| `feature-graphic.png` | Feature graphic | 1024 × 500 |
| `screenshots/phone-*.png` | Phone screenshots (upload at least 2, up to 8) | 1080 × 1920 |
